interface.signature:
Request body — discriminatedUnion('kind'):
  greenfield: { projectId: string }  // existing
  brownfield: { name: string, kind: 'brownfield', gitRepoUrl: string, gitBranch?: string }

Response 201: { jobId: string, projectId: string, projectPath?: string }
Errors: 400 ValidationError (bad URL / name regex / branch whitespace); 409 BOOTSTRAP_IN_PROGRESS

runPartyRefresh(job, ctx): Promise<{ ok: true, lastCommitSha: string, customAgentsSHA: string }>

job.partyRefreshPayload: { projectId: string, projectPath: string, gitBranch: string }
ctx: { pushEvent, updateProjectState, tryAcquireRefreshLock, releaseRefreshLock, updateProjectAfterRefresh, brownfieldToken, expectedAgentCount }

Steps: acquire-lock → git-fetch-reset → compute-sha → verify → read-head-sha → persist → release-lock

selectHandler(job): adds branch — if (job.jobType === 'party-refresh') return JOB_HANDLER_PARTY_REFRESH;

validatePartyRefreshJob(job): { ok: true } | { ok: false; reason: string }
  Required: job.jobId, job.jobType === 'party-refresh', job.partyRefreshPayload.{projectId, projectPath, gitBranch}
